foreach($supervisors as &$availableSupervisor){$availableSupervisor['supervisee_count']=supervisorCurrentLoad($pdo,(int)$availableSupervisor['id'],$studentSemesterId);$availableSupervisor['max_supervisees']=10;}unset($availableSupervisor);
